//! Embed `app.manifest` (Per-Monitor-V2 DPI, asInvoker, no uiAccess) and the
//! app icon (`icon.ico`, generated by tools/make_icon.py) into the .exe. Only relevant for the Windows GNU (mingw) target; a host build skips it.

use std::env;
use std::fs;
use std::path::PathBuf;
use std::process::Command;

fn main() {
    println!("cargo:rerun-if-changed=app.manifest");
    println!("cargo:rerun-if-changed=icon.ico");
    println!("cargo:rerun-if-changed=logo-layers.bin");
    println!("cargo:rerun-if-changed=build.rs");

    let target_os = env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    let target_env = env::var("CARGO_CFG_TARGET_ENV").unwrap_or_default();

    // Only embed the manifest for the Windows GNU target. On a Linux host the
    // target_env is also "gnu", so gate on target_os too.
    if target_os != "windows" || target_env != "gnu" {
        return;
    }

    let manifest_dir = env::var("CARGO_MANIFEST_DIR").unwrap();
    let manifest_path = PathBuf::from(&manifest_dir).join("app.manifest");
    if !manifest_path.exists() {
        return;
    }

    let out_dir = env::var("OUT_DIR").unwrap();
    let rc_path = PathBuf::from(&out_dir).join("manifest.rc");
    let res_path = PathBuf::from(&out_dir).join("manifest.o");

    // 1 = CREATEPROCESS_MANIFEST_RESOURCE_ID, 24 = RT_MANIFEST. 101 = app icon
    // (the first icon resource is what Explorer shows for the .exe).
    let esc = |p: &PathBuf| p.display().to_string().replace('\\', "\\\\");
    // LANGUAGE 0,0 (neutral): logo.rs rewrites the icon resources with that language.
    let mut rc = format!("LANGUAGE 0, 0\n1 24 \"{}\"\n", esc(&manifest_path));
    let icon_path = PathBuf::from(&manifest_dir).join("icon.ico");
    if icon_path.exists() {
        rc += &format!("101 ICON \"{}\"\n", esc(&icon_path));
    }
    fs::write(&rc_path, rc).expect("write manifest.rc");

    let windres = env::var("WINDRES").unwrap_or_else(|_| "x86_64-w64-mingw32-windres".into());
    let status = Command::new(&windres)
        .args(["-O", "coff"])
        .arg(&rc_path)
        .arg(&res_path)
        .status()
        .expect("failed to run windres (needs the mingw-w64 package)");
    assert!(status.success(), "windres failed");

    println!("cargo:rustc-link-arg={}", res_path.display());
}
